// Build a stable dedupe key from the ticket id, and keep the raw text for the LLM.
return items.map((item) => {
  const body = item.json.body || item.json;
  const ticketId = String(body.ticketId || body.id || '').trim();
  const text = String(body.text || body.message || '').trim();

  if (!ticketId) {
    throw new Error('Missing ticketId - cannot dedupe this ticket');
  }
  if (!text) {
    throw new Error('Missing text - nothing to classify');
  }

  return {
    json: {
      eventId: ticketId,
      ticketId,
      text,
      customerEmail: body.email || '',
      receivedAt: new Date().toISOString(),
    },
  };
});

// Parse the model output and pick the target Slack channel.
// Bad or partial JSON never breaks the run: it falls back to category 'other'.
const ALLOWED = ['billing', 'bug', 'howto', 'other'];

return items.map((item) => {
  const choice = item.json.choices && item.json.choices[0];
  const raw = choice && choice.message ? choice.message.content : '{}';

  let parsed = {};
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    parsed = {};
  }

  const ticket = $('Normalise Ticket').item.json;
  const category = ALLOWED.indexOf(parsed.category) >= 0 ? parsed.category : 'other';

  return {
    json: {
      ticketId: ticket.ticketId,
      text: ticket.text,
      category,
      priority: parsed.priority || 'p3',
      summary: parsed.summary || '',
      suggestedReply: parsed.suggested_reply || '',
      channelName: 'support-' + category,
    },
  };
});

// Two jobs, both required:
//  1. Stop the run when the key is already taken. A Postgres node that gets 0 rows emits
//     { success: true } instead of an empty output, so filtering is what actually stops it.
//  2. Put the original payload back. The claim node outputs the SQL row, so without this
//     every downstream node would read fields that no longer exist.
return items
  .filter((item) => item.json && item.json.key)
  .map((item) => ({
    json: Object.assign({}, item.json.payload || {}, { claimKey: item.json.key }),
  }));
